const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const targetDate = '2016-01-13';
  const startDate = '2016-01-12';
  const endDate = '2016-01-14';

  // Southern Ocean belt between 56°S and 68°S
  const region = ee.Geometry.Rectangle({
    coords: [-180, -68, 180, -56],
    geodesic: false
  });

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const collectionSize = await collection.size().getInfo();
  console.log(`Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try Terra as fallback
    collection = ee.ImageCollection('NASA/OCEANDATA/MODIS-Terra/L3SMI')
      .filterDate(startDate, endDate)
      .filterBounds(region);

    const terraSize = await collection.size().getInfo();
    console.log(`Terra images found: ${terraSize}`);

    if (terraSize === 0) {
      console.log('No ocean color data available for this date.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Get chlorophyll-a data
  const image = collection.first();
  const chlorophyll = image.select('chlor_a');

  // Check for valid pixels
  const pixelCount = await chlorophyll.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Valid ocean pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log('No valid ocean pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculate statistics for bloom detection
  const stats = await chlorophyll.reduceRegion({
    reducer: ee.Reducer.percentile([50, 90, 95]),
    geometry: region,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const median = stats['chlor_a_p50'];
  const p90 = stats['chlor_a_p90'];
  const p95 = stats['chlor_a_p95'];

  console.log(`Chlorophyll-a median: ${median ? median.toFixed(3) : 'null'} mg/m³`);
  console.log(`Chlorophyll-a 90th percentile: ${p90 ? p90.toFixed(3) : 'null'} mg/m³`);
  console.log(`Chlorophyll-a 95th percentile: ${p95 ? p95.toFixed(3) : 'null'} mg/m³`);

  // 5. Validation & Final Answer
  if (median === null || median === undefined || isNaN(median)) {
    console.log('Invalid calculation results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Phytoplankton bloom threshold for Southern Ocean
  // Blooms typically show elevated chlorophyll (>0.5 mg/m³, with patches >1.0 mg/m³)
  const bloomThreshold = 0.5;

  if (p90 > bloomThreshold) {
    console.log(`Bloom detected: 90th percentile (${p90.toFixed(3)}) exceeds ${bloomThreshold} mg/m³`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No significant bloom: 90th percentile (${p90.toFixed(3)}) below ${bloomThreshold} mg/m³`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
